from collections import deque
def solve(g, bg):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    # start from any bg cell on the outer boundary connected to (0,0)? use corners
    starts=[(0,0),(0,w-1),(h-1,0),(h-1,w-1)]
    # also full top row? try corners only first
    for r,c in starts:
        if g[r][c]==bg and not seen[r][c]:
            seen[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True; dq.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and not seen[r][c]:
                out[r][c]=3
    return out

